import{_ as t,a,o as i,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"api/introduction.md","filePath":"api/introduction.md","lastUpdated":1787290888000}'),r={name:"api/introduction.md"};function n(s,e,l,d,h,c){return i(),a("div",null,e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Bagisto provides comprehensive API solutions to help developers integrate and extend the platform&#39;s functionality. Whether you&#39;re building mobile apps, third-party integrations, or headless commerce solutions, our APIs offer the flexibility and power you need.</p><p>Both transports expose the <strong>same</strong> data and behaviour — pick the one that fits how you build. Full CRUD, pagination, and token authentication are available on both; the differences below are what actually set them apart.</p><h2 id="graphql-api" tabindex="-1">GraphQL API <a class="header-anchor" href="#graphql-api" aria-label="Permalink to &quot;GraphQL API&quot;">​</a></h2><p>The Bagisto GraphQL API enables flexible, efficient data fetching from a single endpoint. Ideal for:</p><ul><li><strong>Headless Commerce</strong> - Power modern frontend frameworks</li><li><strong>Mobile Apps</strong> - Reduce bandwidth with precise data queries</li><li><strong>Custom Storefronts</strong> - Build unique shopping experiences</li><li><strong>Composite Screens</strong> - Fetch a whole screen&#39;s data in one request</li></ul><p><strong>What sets it apart:</strong></p><ul><li>Single endpoint for every operation</li><li>Fetch exactly the fields you need — no over- or under-fetching</li><li>Related data (product + variants + images, or cart + items + totals) in one round-trip</li><li>Cursor-based pagination</li><li>Typed schema with introspection</li></ul><p>GraphQL suits modern frontend frameworks like React, Vue, and React Native. See the <a href="/api/graphql-api/introduction.html">GraphQL API Guide</a> to get started.</p><h2 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to &quot;REST API&quot;">​</a></h2><p>The Bagisto REST API follows RESTful principles and provides complete access across all Bagisto features. Perfect for:</p><ul><li><strong>Mobile Applications</strong> - Build native iOS/Android shopping apps</li><li><strong>Third-party Integrations</strong> - Connect with external systems and services</li><li><strong>Progressive Web Apps (PWA)</strong> - Create fast, app-like web experiences</li><li><strong>Custom Admin Interfaces</strong> - Build specialized admin tools</li></ul><p><strong>What sets it apart:</strong></p><ul><li>Standard HTTP verbs (GET/POST/PUT/DELETE) and status codes</li><li>One resource per URL — predictable and easy to cache</li><li>Works with any HTTP client — no query language to learn</li><li>Header-based pagination (<code>X-Total-Count</code>, <code>X-Page</code>, <code>X-Per-Page</code>, <code>X-Total-Pages</code>)</li><li>Interactive &quot;try it&quot; documentation</li></ul><p>New to REST? See the <a href="/api/rest-api/introduction.html">REST API Guide</a> for setup and examples.</p><h2 id="build-with-ai" tabindex="-1">Build with AI <a class="header-anchor" href="#build-with-ai" aria-label="Permalink to &quot;Build with AI&quot;">​</a></h2><p>These docs are built for AI coding agents (Claude Code, Codex, Antigravity) as much as for humans. A machine-readable <a href="/llms.txt"><code>llms.txt</code></a> indexes every endpoint, so an agent can discover the whole API surface in one fetch. Point your agent at <strong><a href="/api/build-with-ai/">Build with AI</a></strong> — the hub that ties together every AI resource (<code>llms.txt</code>, agent skills, and the MCP server). Two ways to make an assistant productive on Bagisto:</p><h3 id="agent-skills" tabindex="-1">Agent Skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent Skills&quot;">​</a></h3><p>Installable build-rules that teach an agent the storefront flows, the auth model, and the transport gotchas (<code>token</code> vs <code>apiToken</code>, <code>id</code> vs <code>_id</code>, filter and sort shapes) up front — so it writes correct calls instead of rediscovering them each session. Install once with <code>npx skills add bagisto/agent-skills</code>. See <a href="/api/build-with-ai/agent-skills.html">Agent Skills</a>.</p><h3 id="mcp-server" tabindex="-1">MCP Server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to &quot;MCP Server&quot;">​</a></h3><p>An optional local server that lets an agent search these docs on demand from inside the editor — it pulls the exact request and response for an endpoint mid-task instead of guessing. Runs on your machine, indexes the latest published docs. See <a href="/api/build-with-ai/mcp-server.html">MCP Server</a>.</p><h2 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h2><p>Individual endpoint pages document one call; the <a href="/api/workflows/">Workflows</a> show how to <strong>chain</strong> them into a real task — browse &amp; filter catalog, cart, checkout, customer account, returns, and more — each with a dependency diagram and an ordered call table. Start here (agent or human) when building an end-to-end flow rather than a single request.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><p>Ready to start building? Choose your preferred API approach:</p><ul><li>⚡ <a href="/api/graphql-api/introduction.html">GraphQL API Guide</a> - Modern GraphQL for flexible queries</li><li>🔗 <a href="/api/rest-api/introduction.html">REST API Guide</a> - RESTful API for traditional integrations</li><li>📚 <a href="/api/setup.html">Setup</a> - Installation and setup</li><li>🔐 <a href="/api/authentication.html">Authentication</a> - Authentication methods</li><li>📊 <a href="/api/rate-limiting.html">Rate Limiting</a> - Understanding API rate limits</li><li>🤖 <a href="/api/build-with-ai/">Build with AI</a> - Agent skills, <code>llms.txt</code>, and MCP server</li><li>🧭 <a href="/api/workflows/">Workflows</a> - End-to-end call sequences</li></ul>',26)]))}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
